srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.URL.Path == "/api/v4/version" {
        w.WriteHeader(http.StatusOK)
        w.Write([]byte(`{"version": "16.8.0-ee", "revision": "abc123"}`))
        return
    }
    http.NotFound(w, r)
}))
defer srv.Close()

