forAll(genMethod, genPath, genToken, genPayload, func(method, path, token string, body []byte) bool {
    var captured *http.Request
    srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        captured = r
        w.WriteHeader(http.StatusOK)
        w.Write([]byte("{}"))
    }))
    defer srv.Close()
    c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: token})
    _ = c.do(context.Background(), method, path, body, nil)
    ok := captured.Header.Get("Accept") == "application/json" &&
          captured.Header.Get("User-Agent") != ""
    if token != "" {
        ok = ok && captured.Header.Get("PRIVATE-TOKEN") == token
    } else {
        ok = ok && captured.Header.Get("PRIVATE-TOKEN") == ""
    }
    if len(body) > 0 {
        ok = ok && captured.Header.Get("Content-Type") == "application/json"
    }
    return ok
})

forAll(genOwner, genRepoName, func(owner, name string) bool {
    r := Repo{Owner: owner, Name: name}
    expected := url.PathEscape(r.String())
    expected = strings.ReplaceAll(expected, "/", "%2F")
    return projectPath(r) == expected && !strings.Contains(projectPath(r), "/")
})

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.URL.Path == "/api/v4/projects/org%2Frepo/issues/5" {
        w.Write([]byte(`{
            "iid": 5, "title": "Title", "description": "Desc", "state": "opened",
            "author": {"username": "bob"}, "web_url": "https://gitlab.com/org/repo/-/issues/5"
        }`))
        return
    }
    if r.URL.Path == "/api/v4/projects/org%2Frepo/issues/5/notes" {
        w.Write([]byte(`[
            {"id": 1, "body": "Comment 1", "system": false, "author": {"username": "carol"}},
            {"id": 2, "body": "system note", "system": true, "author": {"username": "gitlab-bot"}}
        ]`))
        return
    }
}))
defer srv.Close()
c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: "tok"})
thread, err := c.ReadIssue(context.Background(), IssueRef{Repo: Repo{Owner: "org", Name: "repo"}, Number: 5})
assert err == nil
assert thread.Issue.Number == 5
assert thread.Issue.State == "open"
assert thread.Issue.IsPR == false
assert len(thread.Comments) == 1
assert thread.Comments[0].Body == "Comment 1"

