srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.Method == "POST" && strings.HasSuffix(r.URL.Path, "/notes") {
        w.WriteHeader(http.StatusCreated)
        w.Write([]byte(`{"id": 42, "body": "a note", "web_url": "https://gitlab.com/note/42"}`))
        return
    }
    if r.Method == "GET" && strings.HasSuffix(r.URL.Path, "/notes") {
        page := r.URL.Query().Get("page")
        if page == "1" {
            w.Header().Set("X-Next-Page", "2")
            w.Write([]byte(`[{"id": 1, "body": "user note", "system": false, "author": {"username": "u"}}, {"id": 2, "body": "audit", "system": true, "author": {"username": "bot"}}]`))
        } else {
            w.Write([]byte(`[]`))
        }
        return
    }
}))
defer srv.Close()

c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: "tok"})
ref := IssueRef{Repo: Repo{Owner: "org", Name: "repo"}, Number: 1}
url, err := c.AddComment(context.Background(), ref, "a note")
assert err == nil
assert url == "https://gitlab.com/note/42"

comments, errList := c.ListComments(context.Background(), ref)
assert errList == nil
assert len(comments.Comments) == 1
assert comments.Comments[0].Body == "user note"
assert comments.Truncated == false

