var closedMR bool
srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.Method == "GET" && strings.HasSuffix(r.URL.Path, "/merge_requests/20") {
        w.Write([]byte(`{"iid": 20, "state": "merged", "sha": "headsha123"}`))
        return
    }
    if r.Method == "PUT" && strings.HasSuffix(r.URL.Path, "/merge_requests/20") {
        var req map[string]any
        json.NewDecoder(r.Body).Decode(&req)
        if req["state_event"] == "close" { closedMR = true }
        w.Write([]byte(`{"iid": 20, "state": "closed"}`))
        return
    }
}))
defer srv.Close()

c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: "tok"})
ref := IssueRef{Repo: Repo{Owner: "org", Name: "repo"}, Number: 20}
state, errState := c.GetPRState(context.Background(), ref)
assert errState == nil
assert state.Number == 20
assert state.State == "merged"
assert state.Merged == true
assert state.HeadSHA == "headsha123"

errClose := c.ClosePullRequest(context.Background(), ref)
assert errClose == nil
assert closedMR == true

srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if strings.HasSuffix(r.URL.Path, "/pipelines") {
        mrID := r.URL.Path
        if strings.Contains(mrID, "merge_requests/1/") {
            w.Write([]byte(`[{"id": 101, "status": "running"}]`))
            return
        }
        w.Write([]byte(`[]`))
        return
    }
    if strings.HasSuffix(r.URL.Path, "/pipelines/101/jobs") {
        w.Write([]byte(`[
            {"id": 1, "name": "lint", "stage": "test", "status": "success", "web_url": "https://gitlab.com/job/1"},
            {"id": 2, "name": "test", "stage": "test", "status": "running", "web_url": "https://gitlab.com/job/2"},
            {"id": 3, "name": "deploy", "stage": "deploy", "status": "failed", "failure_reason": "script_failure", "web_url": "https://gitlab.com/job/3"}
        ]`))
        return
    }
}))
defer srv.Close()

c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: "tok"})
repo := Repo{Owner: "org", Name: "repo"}
checks, err1 := c.GetCIChecks(context.Background(), IssueRef{Repo: repo, Number: 1})
assert err1 == nil
assert len(checks) == 3
assert checks[0].Name == "lint" && checks[0].Status == "completed" && checks[0].Conclusion == "success"
assert checks[1].Name == "test" && checks[1].Status == "in_progress"
assert checks[2].Name == "deploy" && checks[2].Status == "completed" && checks[2].Conclusion == "failure"
assert strings.Contains(checks[2].Summary, "script_failure")

emptyChecks, err2 := c.GetCIChecks(context.Background(), IssueRef{Repo: repo, Number: 2})
assert err2 == nil
assert len(emptyChecks) == 0

var postedReview string
srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    if r.Method == "GET" && strings.HasSuffix(r.URL.Path, "/approvals") {
        w.Write([]byte(`{"approved_by": [{"user": {"username": "reviewer1"}}]}`))
        return
    }
    if r.Method == "GET" && strings.HasSuffix(r.URL.Path, "/notes") {
        w.Write([]byte(`[
            {"id": 1, "body": "Looks good", "system": false, "author": {"username": "reviewer2"}, "created_at": "2025-01-02T00:00:00Z"},
            {"id": 2, "body": "audit event", "system": true, "author": {"username": "bot"}, "created_at": "2025-01-01T00:00:00Z"}
        ]`))
        return
    }
    if r.Method == "POST" && strings.HasSuffix(r.URL.Path, "/notes") {
        var req map[string]any
        json.NewDecoder(r.Body).Decode(&req)
        postedReview = req["body"].(string)
        w.WriteHeader(http.StatusCreated)
        w.Write([]byte(`{"id": 3}`))
        return
    }
}))
defer srv.Close()

c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: "tok"})
ref := IssueRef{Repo: Repo{Owner: "org", Name: "repo"}, Number: 1}
reviews, err := c.GetPRReviews(context.Background(), ref)
assert err == nil
assert len(reviews) == 2
assert reviews[0].State == "approved" && reviews[0].Author.Login == "reviewer1"
assert reviews[1].State == "commented" && reviews[1].Author.Login == "reviewer2"

errPost := c.PostReviewComment(context.Background(), ref, "LGTM")
assert errPost == nil
assert postedReview == "LGTM"

forAll(genErrorMessagePayload, func(payload []byte, expectedMessage string) bool {
    srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        w.WriteHeader(http.StatusBadRequest)
        w.Write(payload)
    }))
    defer srv.Close()
    c := newTestGitLabClient(Options{BaseURL: srv.URL, Token: "tok"})
    _, err := c.do(context.Background(), "GET", "/err", nil, nil)
    return err != nil && strings.Contains(err.Error(), expectedMessage)
})
